-- A call with a lambda is a value like any other: it filters, and a selector takes an element of
-- what it returns. The filter is on a selection of the filtered list, which is NULL for an empty
-- one; list_reduce would refuse it.
SELECT
  t.nr
, (SELECT E1.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT upper(LA0.X) FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.tags) Z) LA0 ORDER BY LA0.I) AS SYS.ODCIVARCHAR2LIST) END) Z) E1 WHERE E1.RN = 1) AS first_shouted
, (SELECT E1.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 WHERE LA0.X > 5 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END) Z) E1 WHERE E1.RN = 1) AS first_big
, (SELECT E1.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(CASE WHEN t.items IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X.sku FROM (SELECT VALUE(Z) X, ROWNUM I FROM TABLE(t.items) Z) LA0 ORDER BY LA0.I) AS SYS.ODCIVARCHAR2LIST) END) Z) E1 WHERE E1.RN = (SELECT COUNT(*) FROM TABLE(CASE WHEN t.items IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X.sku FROM (SELECT VALUE(Z) X, ROWNUM I FROM TABLE(t.items) Z) LA0 ORDER BY LA0.I) AS SYS.ODCIVARCHAR2LIST) END)) - 1 + 1) AS last_sku
FROM
 check_complex t
WHERE
  (SELECT E1.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 WHERE LA0.X > 5 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END) Z) E1 WHERE E1.RN = 1) > 5